# Completa la línea marcada y compruébala con py check.
def top_p(probs, p):
    orden = sorted(range(len(probs)), key=lambda i: -probs[i])
    elegidos, suma = [], 0
    for i in orden:
        elegidos.append(i)
        suma += probs[i]
        # ← añade aquí: para en cuanto la suma llegue a p
    return sorted(elegidos)

print(top_p([0.1, 0.6, 0.3], 0.8))   # [1, 2]
